-- RAW production migration applied to the connected Supabase project.
-- Key rules: email/password auth only; no OTP; private student data; no direct answer-key exposure.

alter table public.profiles add column if not exists full_name text;
create table if not exists public.student_profiles(id uuid primary key references public.profiles(id) on delete cascade,education_level text,class_name text,primary_exam text,exam_date date,preferred_language text not null default 'en',study_hours numeric(4,2),onboarding_completed boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.chapters(id bigint generated by default as identity primary key,subject_id bigint references public.subjects(id) on delete cascade,name text not null,slug text not null,order_index int not null default 0,status text not null default 'draft',unique(subject_id,slug));
create table if not exists public.material_sources(id bigint generated by default as identity primary key,provider text not null,title text not null,source_url text not null,license_note text,last_verified_at timestamptz,status text not null default 'unverified');
create table if not exists public.study_materials(id bigint generated by default as identity primary key,topic_id bigint references public.topics(id) on delete set null,source_id bigint references public.material_sources(id) on delete set null,title text not null,material_type text not null,external_url text,storage_path text,status text not null default 'draft',created_at timestamptz not null default now());
create table if not exists public.practice_sessions(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,started_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.question_attempts(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,session_id uuid references public.practice_sessions(id) on delete cascade,question_id bigint not null references public.questions(id),selected_option_ids jsonb not null default '[]',is_correct boolean not null,time_taken_seconds int,created_at timestamptz not null default now());
create table if not exists public.mistakes(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,question_id bigint not null references public.questions(id),attempt_id uuid references public.question_attempts(id) on delete cascade,category text,created_at timestamptz not null default now());
create table if not exists public.mastery(student_id uuid not null references public.profiles(id) on delete cascade,topic_id bigint not null references public.topics(id) on delete cascade,mastery numeric not null default 0 check(mastery between 0 and 1),attempts int not null default 0,updated_at timestamptz not null default now(),primary key(student_id,topic_id));
create table if not exists public.tests(id uuid primary key default gen_random_uuid(),title text not null,test_type text not null,duration_minutes int not null,status text not null default 'draft',created_at timestamptz not null default now());
create table if not exists public.test_questions(test_id uuid not null references public.tests(id) on delete cascade,question_id bigint not null references public.questions(id),order_index int not null,primary key(test_id,question_id));
create table if not exists public.test_attempts(id uuid primary key default gen_random_uuid(),test_id uuid not null references public.tests(id),student_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'in_progress',started_at timestamptz not null default now(),submitted_at timestamptz);
create table if not exists public.test_answers(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references public.test_attempts(id) on delete cascade,question_id bigint not null references public.questions(id),selected_option_ids jsonb not null default '[]',numerical_answer numeric,updated_at timestamptz not null default now(),unique(attempt_id,question_id));
create table if not exists public.test_results(attempt_id uuid primary key references public.test_attempts(id) on delete cascade,score numeric not null,accuracy numeric not null,correct_count int not null,incorrect_count int not null,unanswered_count int not null,subject_breakdown jsonb not null default '{}',topic_breakdown jsonb not null default '{}',computed_at timestamptz not null default now());
create table if not exists public.revision_items(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,topic_id bigint references public.topics(id) on delete set null,due_at timestamptz not null,interval_days int not null default 1,completed_at timestamptz);
create table if not exists public.study_plans(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,name text not null,start_date date,end_date date,schedule jsonb not null default '{}');
create table if not exists public.study_tasks(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,title text not null,source_type text,source_id text,due_at timestamptz,completed boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.bookmarks(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,entity_type text not null,entity_id text not null,created_at timestamptz not null default now(),unique(student_id,entity_type,entity_id));
create table if not exists public.student_notes(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,title text not null default 'Untitled',body text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.uploaded_documents(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,storage_path text not null,filename text not null,mime_type text not null,size_bytes bigint not null,status text not null default 'uploaded',created_at timestamptz not null default now());
create table if not exists public.ai_sessions(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,title text,created_at timestamptz not null default now());
create table if not exists public.ai_messages(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.ai_sessions(id) on delete cascade,role text not null check(role in('user','assistant','system')),content text not null,created_at timestamptz not null default now());
create table if not exists public.friends(requester_id uuid not null references public.profiles(id) on delete cascade,addressee_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending',created_at timestamptz not null default now(),primary key(requester_id,addressee_id),check(requester_id<>addressee_id));
create table if not exists public.study_groups(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null,description text,created_at timestamptz not null default now());
create table if not exists public.group_members(group_id uuid not null references public.study_groups(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,role text not null default 'member',created_at timestamptz not null default now(),primary key(group_id,student_id));
create table if not exists public.community_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id) on delete cascade,body text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.community_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.community_posts(id) on delete cascade,author_id uuid not null references public.profiles(id) on delete cascade,body text not null,created_at timestamptz not null default now());
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,entity_type text not null,entity_id text not null,reason text not null,status text not null default 'open',created_at timestamptz not null default now());

alter table public.questions enable row level security;
drop policy if exists questions_public_read on public.questions;
create policy questions_published_safe_read on public.questions for select to authenticated using(true);
revoke select on public.questions from anon,authenticated;
create or replace view public.published_questions with (security_invoker=true) as select id,subject_id,topic_id,exam_id,question_text,question_type,difficulty,options,created_at from public.questions;
grant select on public.published_questions to authenticated;

create table if not exists public.question_keys(question_id bigint primary key references public.questions(id) on delete cascade,correct_answer text,explanation text not null default '');
alter table public.question_keys enable row level security;
drop policy if exists question_keys_public on public.question_keys;
create policy question_keys_none on public.question_keys for all to authenticated using(false) with check(false);

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['student_profiles','practice_sessions','question_attempts','mistakes','mastery','test_attempts','test_answers','test_results','revision_items','study_plans','study_tasks','bookmarks','student_notes','uploaded_documents','ai_sessions','ai_messages','friends','study_groups','group_members','reports'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;

create index if not exists idx_question_attempts_student on public.question_attempts(student_id,created_at desc);create index if not exists idx_study_tasks_student_due on public.study_tasks(student_id,due_at);create index if not exists idx_mastery_student_updated on public.mastery(student_id,updated_at desc);

-- IMPORTANT: authoritative scoring, rankings and AI calls must be server-side Edge Functions. Never calculate authoritative results only in browser storage.